export const getStartTorrentDownloadUrl = () => {
  return `/v1/torrent/downloads`
}

/**
 * Envia o magnet ao qBittorrent, que baixa na pasta de trabalho. O destino, para onde os
 * arquivos são movidos quando o download termina, é a pasta do anime na biblioteca: a já
 * vinculada a ele ou, se ele ainda não tem nenhuma, uma pasta nova `<título romaji>` no
 * provider da biblioteca, vinculada a ele na hora.
 *
 * Idempotente pelo info-hash do magnet: uma release que já está baixando ou já foi baixada
 * é devolvida como está, sem enviar de novo.
 * @summary Baixa uma release de torrent para a pasta do anime na biblioteca
 */
export const startTorrentDownload = async (
  torrentDownloadRequestBodyBody: TorrentDownloadRequestBodyBody,
  options?: Parameters<typeof apiFetch>[1],
): Promise<TorrentDownloadCreatedResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit['headers']>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {}
    if (h instanceof Headers) return Object.fromEntries(h.entries())
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      )
    }
    const headers: Record<string, string | readonly string[]> = {}
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value
    }
    return headers
  }
  return apiFetch<TorrentDownloadCreatedResponse>(
    getStartTorrentDownloadUrl(),
    {
      ...options,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(torrentDownloadRequestBodyBody),
    },
  )
}

